todo_id = params.get("todo_id") or ""
responses = params.get("responses") or {}
manual_client = str(params.get("client_name") or "").strip()
answer = str(bk_answer(responses, "q_action") or "").lower()
problem = ""
ctx = {}

if todo_id:
    action = "check" if answer.startswith("run") else ("cancel" if answer.startswith("cancel") else "")
else:
    action = "check" if manual_client else ""
path, run = pay_run_load(todo_id, manual_client) if action else ("", {})
settings = bk_read_json(BK_SETTINGS) or {}

if action and not run:
    action = ""
    problem = "There's no open pay run for " + (manual_client or "this item") + "."
elif action:
    note = str(bk_answer(responses, "q_notes") or "").strip()
    if note:
        run.setdefault("notes", []).append({"at": bk_now_iso(settings), "by": params.get("actor") or "", "text": note[:4000]})
    if action == "cancel":
        run["status"] = "cancelled"
        api.workq.comment(todo_id=run["item_id"], body="Pay run cancelled. Nothing was changed in Xero Payroll.")
        api.workq.complete(todo_id=run["item_id"])
        action = ""
    bk_write_json(path, run)
    if action:
        client = bk_client_for(settings, run["slug"]) or {}
        payroll = bk_read_json(BK_PAYROLL + "/" + run["slug"] + ".json") or {}
        if not client.get("xero_tenant_id"):
            problem = "The bookkeeping settings for " + run["name"] + " have no Xero organisation."
        ctx = {"settings": settings, "client": client, "payroll": payroll, "run": run, "run_path": path}

should_check = action == "check" and not problem
if problem and run.get("item_id"):
    api.workq.comment(todo_id=run["item_id"], body="The checks didn't run: " + problem)

# ── bookkeeping kit: shared helpers (inlined into each node by gen-ext.js) ──
import json
import re
import datetime
from zoneinfo import ZoneInfo

# Knowledge layout. Folders may nest at most 2 levels, so inbox folders are top-level.
BK_SETTINGS = "Bookkeeping/settings.json"
BK_CLIENTS = "Bookkeeping/Clients"
BK_RULES = "Bookkeeping/Rules"
BK_BILLS = "Bookkeeping/Bills"
BK_INBOX = "Bookkeeping Inbox"
BK_PROCESSED = "Bookkeeping Processed"
BK_FAILED = "Bookkeeping Failed"
BK_MAIL = "Bookkeeping/Mail"
BK_REQUESTS = "Bookkeeping Requests"


def bk_money(value):
    """Parse 1234.5, "1,234.50", "$12" or "A$ 12.00" into a float; None when blank or not a number."""
    if value is None or isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return float(value)
    s = re.sub(r"[^0-9.\-]", "", str(value))
    if s in ("", "-", ".", "-."):
        return None
    try:
        return float(s)
    except ValueError:
        return None


def bk_tz(settings):
    # The sandbox may lack the tz database; fall back to AEST (UTC+10) rather than failing the run.
    try:
        return ZoneInfo((settings or {}).get("timezone") or "Australia/Sydney")
    except Exception:
        return datetime.timezone(datetime.timedelta(hours=10))


def bk_norm(name):
    s = re.sub(r"[^a-z0-9 ]+", " ", str(name or "").lower())
    s = re.sub(r"\b(pty|ltd|limited|p/l|the|inc|co)\b", " ", s)
    return re.sub(r"\s+", " ", s).strip()


# ── bookkeeping kit: payroll adapter (inlined into payroll nodes by gen-ext.js) ──
# Xero Payroll AU through xero-payroll-au (reads take xero_tenant_id, so each call lands in the client's own
# organisation) and Deputy through deputy. Read-only: the checks list corrections, the payroll officer makes them.
import csv
import io

from openpyxl import Workbook, load_workbook

BK_PAYROLL = "Bookkeeping/Payroll"
BK_PAYRUNS = "Bookkeeping/PayRuns"
BK_PAYROLL_FILES = "Bookkeeping Payroll"
PAYROLL = "xero-payroll-au"
DEPUTY = "deputy"
PAY_WEEKDAYS = ["Monday", "Tuesday", "Wednesday", "Thursday", "Friday", "Saturday", "Sunday"]
PAY_BANDS = ["ordinary", "early", "late", "saturday", "sunday", "public_holiday", "ot_first", "ot_after"]
PAY_BAND_NAMES = {"ordinary": "ordinary", "early": "early (before start of day)", "late": "late (after end of day)",
                  "saturday": "Saturday", "sunday": "Sunday", "public_holiday": "public holiday",
                  "ot_first": "overtime (first hours)", "ot_after": "overtime (after that)"}


def pay_call(tool, tenant_id=None, **args):
    if tenant_id:
        args["xero_tenant_id"] = tenant_id
    exc = None  # bound first for the platform lint (see xero_call)
    try:
        return api.connectors.invoke(server=PAYROLL, tool=tool, args=args)
    except Exception as exc:
        raise RuntimeError("Xero Payroll: " + str(exc)[:500]) from None


def pay_rows(result, key):
    if isinstance(result, dict):
        rows = result.get(key)
        return rows if isinstance(rows, list) else []
    return result if isinstance(result, list) else []


def pay_date(value):
    """Xero Payroll dates arrive as '/Date(1759276800000+0000)/' or ISO; Deputy's as ISO or epoch seconds."""
    s = str(value or "")
    m = re.match(r"/Date\((-?\d+)", s)
    if m:
        return datetime.datetime.fromtimestamp(int(m.group(1)) / 1000, datetime.timezone.utc).date()
    try:
        return datetime.date.fromisoformat(s[:10])
    except ValueError:
        return None


def pay_xero_dt(d):
    return "DateTime(%d,%d,%d)" % (d.year, d.month, d.day)


def pay_name(e):
    return re.sub(r"\s+", " ", (str(e.get("FirstName") or "") + " " + str(e.get("LastName") or "")).strip())


def pay_employees(tenant_id, calendar_id=""):
    """Active employees (full records, one get_employee each), optionally only those on the pay calendar."""
    out = []
    for page in range(1, 11):
        rows = pay_rows(pay_call("list_employees", tenant_id, where='Status=="ACTIVE"', page=page), "Employees")
        for r in rows:
            if calendar_id and r.get("PayrollCalendarID") and r.get("PayrollCalendarID") != calendar_id:
                continue
            full = pay_rows(pay_call("get_employee", tenant_id, employeeId=r["EmployeeID"]), "Employees")
            out.append(full[0] if full else r)
        if len(rows) < 100:
            break
    return out


def pay_basis(e):
    basis = str(((e.get("TaxDeclaration") or {}).get("EmploymentBasis")) or e.get("EmploymentBasis") or "").upper()
    return {"FULLTIME": "full-time", "PARTTIME": "part-time", "CASUAL": "casual"}.get(basis, basis.lower() or "unknown")


def pay_items(tenant_id):
    items = (pay_call("list_pay_items", tenant_id) or {})
    items = items.get("PayItems", items) if isinstance(items, dict) else {}
    earnings = {r.get("EarningsRateID"): r for r in (items.get("EarningsRates") or []) if isinstance(r, dict)}
    return {"earnings": earnings}


def pay_timesheets(tenant_id, start, end):
    where = "StartDate>=%s AND EndDate<=%s" % (pay_xero_dt(start), pay_xero_dt(end))
    return pay_rows(pay_call("list_timesheets", tenant_id, where=where), "Timesheets")


def pay_draft_run(tenant_id, calendar_id, start):
    """The draft pay run for the period with its payslip summaries, or None."""
    where = 'PayrollCalendarID==Guid("%s") AND PayRunStatus=="DRAFT"' % calendar_id
    for r in pay_rows(pay_call("list_pay_runs", tenant_id, where=where), "PayRuns"):
        if pay_date(r.get("PayRunPeriodStartDate")) == start:
            full = pay_rows(pay_call("get_pay_run", tenant_id, payRunId=r["PayRunID"]), "PayRuns")
            return full[0] if full else r
    return None


def deputy_rows(tool, **args):
    out = []
    for page in range(20):
        rows = api.connectors.invoke(server=DEPUTY, tool=tool, args=dict(args, max=500, start=page * 500))
        rows = rows if isinstance(rows, list) else (rows or {}).get("data") or []
        out.extend(r for r in rows if isinstance(r, dict))
        if len(rows) < 500:
            break
    return out


def pay_band_of(name, mapping):
    """Which band a Xero earnings rate pays, from the pay guide's pay_items sheet or its name."""
    n = bk_norm(name)
    if n in mapping:
        return mapping[n]
    if "public holiday" in n or re.search(r"\bph\b", n):
        return "public_holiday"
    if "saturday" in n or re.search(r"\bsat\b", n):
        return "saturday"
    if "sunday" in n or re.search(r"\bsun\b", n):
        return "sunday"
    if "overtime" in n or re.search(r"\bot\b", n):
        return "ot_after" if ("after" in n or "thereafter" in n) else "ot_first"
    if "before 7" in n or "early" in n:
        return "early"
    if "after 6" in n or "late" in n or "evening" in n:
        return "late"
    return "ordinary"


def pay_guide(path):
    """The client's pay guide workbook as plain data, or None when there's no file. Sheets (any order, headers in row 1):
    rates (award, classification, basis, age_from, age_to, band, rate, effective_from); employees (employee, award,
    classification, state, special_rate, special_until, notes); rules (award, day_start, day_end, ot_after_hours,
    ot_first_hours); holidays (date, state, name); pay_items (pay_item, band)."""
    try:
        local = api.files.get(file=path)
    except Exception:
        return None
    book = load_workbook(local, read_only=True, data_only=True)
    guide = {"rates": [], "employees": {}, "rules": {}, "holidays": {}, "pay_items": {}}
    for ws in book.worksheets:
        rows = [list(r) for r in ws.iter_rows(values_only=True)]
        if not rows:
            continue
        head = [bk_norm(h).replace(" ", "_") for h in rows[0]]
        recs = [dict(zip(head, r)) for r in rows[1:] if any(v not in (None, "") for v in r)]
        title = bk_norm(ws.title).replace(" ", "_")
        if title == "rates":
            for r in recs:
                band = str(r.get("band") or "ordinary").strip().lower().replace(" ", "_")
                guide["rates"].append({"award": bk_norm(r.get("award")), "classification": bk_norm(r.get("classification")),
                                       "basis": bk_norm(r.get("basis")) or "casual", "age_from": bk_money(r.get("age_from")),
                                       "age_to": bk_money(r.get("age_to")), "band": band, "rate": bk_money(r.get("rate")),
                                       "effective_from": str(pay_date(r.get("effective_from")) or "")})
        elif title == "employees":
            for r in recs:
                guide["employees"][bk_norm(r.get("employee"))] = {
                    "award": bk_norm(r.get("award")), "classification": bk_norm(r.get("classification")),
                    "state": str(r.get("state") or "").strip().upper(), "special_rate": bk_money(r.get("special_rate")),
                    "special_until": str(pay_date(r.get("special_until")) or ""), "notes": str(r.get("notes") or "")}
        elif title == "rules":
            for r in recs:
                guide["rules"][bk_norm(r.get("award"))] = {
                    "day_start": str(r.get("day_start") or "07:00")[:5], "day_end": str(r.get("day_end") or "18:00")[:5],
                    "ot_after_hours": bk_money(r.get("ot_after_hours")), "ot_first_hours": bk_money(r.get("ot_first_hours")) or 0}
        elif title == "holidays":
            for r in recs:
                d = pay_date(r.get("date"))
                for st in [s.strip().upper() for s in str(r.get("state") or "ALL").split(",") if s.strip()]:
                    if d:
                        guide["holidays"].setdefault(st, []).append(str(d))
        elif title == "pay_items":
            for r in recs:
                guide["pay_items"][bk_norm(r.get("pay_item"))] = str(r.get("band") or "ordinary").strip().lower().replace(" ", "_")
    return guide


def pay_rate(guide, award, classification, basis, age, band, on_date):
    """The pay guide's rate for this employee and band on a date, or None."""
    best = None
    for r in (guide or {}).get("rates") or []:
        if r["award"] != award or r["classification"] != classification or r["band"] != band or r["rate"] is None:
            continue
        if r["basis"] not in (basis, "any"):
            continue
        if age is not None and ((r["age_from"] is not None and age < r["age_from"]) or (r["age_to"] is not None and age > r["age_to"])):
            continue
        if r["effective_from"] and r["effective_from"] > str(on_date):
            continue
        if best is None or r["effective_from"] > best["effective_from"]:
            best = r
    return best["rate"] if best else None


def pay_hm(text, default):
    m = re.match(r"(\d{1,2}):(\d{2})", str(text or ""))
    return (int(m.group(1)), int(m.group(2))) if m else default


def pay_split(start_dt, end_dt, worked_hours, rule, holidays):
    """A shift's worked hours by band: public holiday, Saturday, Sunday, else early / ordinary / late by the award's
    day start and end; then daily overtime past the award's threshold. Breaks are spread pro rata."""
    span = (end_dt - start_dt).total_seconds() / 3600
    hours = worked_hours if worked_hours is not None else span
    bands = {b: 0.0 for b in PAY_BANDS}
    if span <= 0 or hours <= 0:
        return bands
    day = start_dt.date()
    if str(day) in holidays:
        bands["public_holiday"] = hours
    elif day.weekday() == 5:
        bands["saturday"] = hours
    elif day.weekday() == 6:
        bands["sunday"] = hours
    else:
        sh, sm = pay_hm(rule.get("day_start"), (7, 0))
        eh, em = pay_hm(rule.get("day_end"), (18, 0))
        day_start = start_dt.replace(hour=sh, minute=sm, second=0, microsecond=0)
        day_end = start_dt.replace(hour=eh, minute=em, second=0, microsecond=0)
        early = max(0.0, (min(end_dt, day_start) - start_dt).total_seconds() / 3600)
        late = max(0.0, (end_dt - max(start_dt, day_end)).total_seconds() / 3600)
        scale = hours / span
        bands["early"] = round(early * scale, 4)
        bands["late"] = round(late * scale, 4)
        bands["ordinary"] = round(hours - bands["early"] - bands["late"], 4)
        limit = rule.get("ot_after_hours")
        if limit and hours > limit:
            ot = hours - limit
            first = min(ot, rule.get("ot_first_hours") or 0)
            bands["ot_first"], bands["ot_after"] = round(first, 4), round(ot - first, 4)
            for b in ("ordinary", "late", "early"):
                take = min(bands[b], ot)
                bands[b] = round(bands[b] - take, 4)
                ot -= take
    return bands


def pay_table(path):
    """Rows of a spreadsheet or CSV in Knowledge as dicts keyed by normalised header (first row that has one)."""
    local = api.files.get(file=path)
    if path.lower().endswith(".csv"):
        with open(local, encoding="utf-8-sig", errors="replace") as fh:
            rows = list(csv.reader(io.StringIO(fh.read())))
    else:
        book = load_workbook(local, read_only=True, data_only=True)
        rows = [list(r) for r in book.worksheets[0].iter_rows(values_only=True)]
    for i, r in enumerate(rows[:20]):
        head = [bk_norm(h) for h in r]
        if any(h in ("employee", "name", "employee name", "staff") for h in head) and any(
                ("amount" in h or "total" in h) for h in head):
            return [dict(zip(head, x)) for x in rows[i + 1:] if any(v not in (None, "") for v in x)]
    return []


# ── Check the pay run ──


provider = params["provider"]
problem = params.get("problem") or ""
ctx = params.get("ctx") or {}
findings = {}

if not problem:
    try:
        settings = ctx.get("settings") or {}
        client = ctx.get("client") or {}
        ps = ctx.get("payroll") or {}
        run = ctx.get("run") or {}
        tenant = client["xero_tenant_id"]
        start = datetime.date.fromisoformat(run["period_start"])
        end = datetime.date.fromisoformat(run["period_end"])
        tz = bk_tz(settings)
        notes = []

        guide = pay_guide(BK_PAYROLL_FILES + "/" + run["slug"] + "/pay-guide.xlsx")
        if not guide:
            notes.append("There's no pay guide in `" + BK_PAYROLL_FILES + "/" + run["slug"] + "/pay-guide.xlsx`, so rates and "
                         "penalty bands weren't checked.")
        mapping = (guide or {}).get("pay_items") or {}
        items = pay_items(tenant)["earnings"]

        # ── Who is on this pay calendar ──
        people = {}
        for e in pay_employees(tenant, (run.get("calendar") or {}).get("id") or ""):
            name = pay_name(e)
            key = bk_norm(name)
            dob = pay_date(e.get("DateOfBirth"))
            age = (end.year - dob.year - ((end.month, end.day) < (dob.month, dob.day))) if dob else None
            g = ((guide or {}).get("employees") or {}).get(key) or {}
            template = {}
            for line in ((e.get("PayTemplate") or {}).get("EarningsLines") or []):
                if line.get("EarningsRateID") and bk_money(line.get("RatePerUnit")) is not None:
                    template[line["EarningsRateID"]] = bk_money(line.get("RatePerUnit"))
            people[key] = {"id": e.get("EmployeeID"), "name": name, "basis": pay_basis(e), "dob": dob, "age": age,
                           "ordinary_id": e.get("OrdinaryEarningsRateID") or "",
                           "state": g.get("state") or str(((e.get("HomeAddress") or {}).get("Region")) or "").upper(),
                           "award": g.get("award") or "", "classification": g.get("classification") or "",
                           "special_rate": g.get("special_rate"), "special_until": g.get("special_until") or "",
                           "in_guide": bool(g), "template": template, "xero_days": {}, "xero_bands": {}, "xero_rates": {},
                           "deputy_days": {}, "deputy_bands": {}, "shifts": 0}
        by_id = {p["id"]: p for p in people.values()}

        # ── Hours in Xero Payroll, by day and by band ──
        for t in pay_timesheets(tenant, start, end):
            p = by_id.get(t.get("EmployeeID"))
            if not p:
                continue
            t_start = pay_date(t.get("StartDate")) or start
            for line in t.get("TimesheetLines") or []:
                er = items.get(line.get("EarningsRateID")) or {}
                band = pay_band_of(er.get("Name"), mapping)
                rate = p["template"].get(line.get("EarningsRateID"))
                if rate is None:
                    rate = bk_money(er.get("RatePerUnit"))
                for i, units in enumerate(line.get("NumberOfUnits") or []):
                    u = bk_money(units) or 0
                    if not u:
                        continue
                    d = str(t_start + datetime.timedelta(days=i))
                    p["xero_days"][d] = round(p["xero_days"].get(d, 0) + u, 4)
                    p["xero_bands"][band] = round(p["xero_bands"].get(band, 0) + u, 4)
                    if rate is not None:
                        p["xero_rates"][band] = rate

        # ── Hours in Deputy ──
        deputy_on = provider == "deputy" and ps.get("timesheets") == "deputy"
        missing_starters = []
        if ps.get("timesheets") == "deputy" and provider != "deputy":
            notes.append("This client's hours come from Deputy, but this is the version of the check without Deputy. "
                         "Publish *Check pay run (Xero Payroll + Deputy)* to compare Deputy with Xero.")
        if deputy_on:
            staff = {r.get("Id"): r for r in deputy_rows("list_employees")}
            for ts in deputy_rows("list_timesheets", date_from=str(start), date_to=str(end)):
                de = staff.get(ts.get("Employee")) or {}
                dname = str(de.get("DisplayName") or (str(de.get("FirstName") or "") + " " + str(de.get("LastName") or ""))).strip()
                hours = bk_money(ts.get("TotalTime")) or 0
                p = people.get(bk_norm(dname))
                if not p:
                    if hours and dname not in missing_starters:
                        missing_starters.append(dname)
                    continue
                st, en = ts.get("StartTime"), ts.get("EndTime")
                sdt = datetime.datetime.fromtimestamp(int(st), tz) if isinstance(st, (int, float)) else None
                edt = datetime.datetime.fromtimestamp(int(en), tz) if isinstance(en, (int, float)) else None
                d = str(sdt.date()) if sdt else str(pay_date(ts.get("Date")) or "")
                p["deputy_days"][d] = round(p["deputy_days"].get(d, 0) + hours, 4)
                if sdt and edt and guide:
                    rule = guide["rules"].get(p["award"]) or {}
                    holidays = set((guide["holidays"].get(p["state"]) or []) + (guide["holidays"].get("ALL") or []))
                    for band, v in pay_split(sdt, edt, hours, rule, holidays).items():
                        if v:
                            p["deputy_bands"][band] = round(p["deputy_bands"].get(band, 0) + v, 4)
                    p["shifts"] += 1

        hours_diff, salaried, bands_diff, rates_diff, unclassified, changes = [], [], [], [], [], []
        for p in sorted(people.values(), key=lambda x: x["name"]):
            worked = sum(p["xero_days"].values()) + sum(p["deputy_days"].values())
            if p["basis"] == "full-time" and p["xero_days"]:
                salaried.append({"name": p["name"], "hours": round(sum(p["xero_days"].values()), 2)})
            if deputy_on and p["basis"] != "full-time":
                for d in sorted(set(p["xero_days"]) | set(p["deputy_days"])):
                    a, b = p["deputy_days"].get(d, 0), p["xero_days"].get(d, 0)
                    if abs(a - b) > 0.02:
                        hours_diff.append({"name": p["name"], "date": d, "deputy": round(a, 2), "xero": round(b, 2)})
            if p["basis"] in ("casual", "part-time") and worked and guide and not p["in_guide"]:
                unclassified.append(p["name"])
            # A special arrangement in effect for any part of the period still sets the rate; the change note covers the switch.
            special = p["special_rate"] is not None and (not p["special_until"] or p["special_until"] >= str(start))
            if guide and p["in_guide"] and p["basis"] in ("casual", "part-time"):
                if p["shifts"]:
                    for band in PAY_BANDS:
                        a, b = p["deputy_bands"].get(band, 0), p["xero_bands"].get(band, 0)
                        if abs(a - b) > 0.05:
                            bands_diff.append({"name": p["name"], "band": band, "expected": round(a, 2), "xero": round(b, 2)})
                for band in PAY_BANDS:
                    if not (p["xero_bands"].get(band) or p["deputy_bands"].get(band)):
                        continue
                    want = p["special_rate"] if special else pay_rate(guide, p["award"], p["classification"], p["basis"],
                                                                     p["age"], band, end)
                    have = p["xero_rates"].get(band)
                    if have is None and band == "ordinary":
                        have = p["template"].get(p["ordinary_id"])
                    if want is None:
                        rates_diff.append({"name": p["name"], "band": band, "expected": None, "xero": have,
                                           "note": "no rate in the pay guide for " + p["award"] + " / " + p["classification"]})
                    elif have is not None and abs(want - have) > 0.005:
                        rates_diff.append({"name": p["name"], "band": band, "expected": want, "xero": have,
                                           "note": "special arrangement" if special else ""})
            # Upcoming changes in this period
            if p["dob"] and p["age"] is not None and p["age"] <= 21:
                for year in (start.year, end.year):
                    try:
                        bday = p["dob"].replace(year=year)
                    except ValueError:
                        bday = datetime.date(year, 3, 1)
                    if start <= bday <= end:
                        changes.append({"name": p["name"], "text": "turns " + str(year - p["dob"].year) + " on " + str(bday)
                                        + ": check the junior rate from that day"})
                        break
            if p["special_until"] and str(start) <= p["special_until"] <= str(end):
                changes.append({"name": p["name"], "text": "special arrangement ends " + p["special_until"]
                                + ": move them to the award rate and penalties from that day"})
            elif p["special_until"] and p["special_until"] < str(start) and p["special_rate"] is not None and \
                    p["special_rate"] in p["xero_rates"].values():
                changes.append({"name": p["name"], "text": "special arrangement ended " + p["special_until"]
                                + " but Xero still pays the special rate"})
        for year in (start.year, end.year):
            july = datetime.date(year, 7, 1)
            if start <= july <= end:
                changes.append({"name": "Everyone on an award", "text": "award rates rise from 1 July: check the new pay "
                                "items are in Xero, the old ones archived, and the pay guide has the new rates"})
                break

        # ── Draft pay run and reimbursements ──
        draft = pay_draft_run(tenant, (run.get("calendar") or {}).get("id") or "", start)
        totals = {}
        slips = {}
        if draft:
            totals = {k: bk_money(draft.get(k)) for k in ("Wages", "Tax", "Super", "Deductions", "Reimbursement", "NetPay")}
            for s in draft.get("Payslips") or []:
                slips[bk_norm(pay_name(s))] = s
        else:
            notes.append("There's no draft pay run in Xero Payroll for " + run["period_start"] + " yet, so pay run totals and "
                         "reimbursements weren't compared.")
        reimburse = []
        files = [f for f in api.files.list(path=BK_PAYROLL_FILES + "/" + run["slug"])
                 if re.search(r"expense|reimburs", str(f.get("name") or ""), re.I)
                 and str(f.get("name") or "").lower().endswith((".xlsx", ".csv"))]
        if files:
            newest = sorted(files, key=lambda f: str(f.get("modifiedAt") or ""))[-1]
            owed = {}
            for row in pay_table(newest["path"]):
                who = next((row[k] for k in ("employee", "employee name", "name", "staff") if row.get(k)), None)
                amount_key = next((k for k in row if "total" in k), None) or next((k for k in row if "amount" in k), None)
                amount = bk_money(row.get(amount_key)) if amount_key else None
                if who and amount is not None and bk_norm(who) not in ("total", "grand total"):
                    owed[bk_norm(who)] = (str(who), round(owed.get(bk_norm(who), ("", 0))[1] + amount, 2))
            for key, (who, amount) in sorted(owed.items()):
                paid = bk_money((slips.get(key) or {}).get("Reimbursements")) if draft else None
                if draft and abs((paid or 0) - amount) > 0.01:
                    reimburse.append({"name": who, "file": amount, "pay_run": paid or 0})
            notes.append("Reimbursements checked against `" + newest["path"] + "` (" + str(len(owed)) + " employees).")

        findings = {
            "period": run["period_start"] + " to " + run["period_end"], "employees": len(people), "deputy": deputy_on,
            "missing_starters": missing_starters, "salaried_timesheets": salaried, "hours": hours_diff,
            "bands": bands_diff, "rates": rates_diff, "unclassified": unclassified, "changes": changes,
            "reimbursements": reimburse, "totals": totals, "draft_pay_run": bool(draft), "notes": notes,
        }
    except Exception as exc:
        problem = "The checks couldn't finish: " + str(exc)[:500]
